// legacyFixture copies a starter generated by wsup 0.2.0 into a new folder.
func legacyFixture(t *testing.T, name string) string {
	t.Helper()
	source := filepath.Join("testdata", "v0.2.0", name)
	root := filepath.Join(t.TempDir(), name)
	err := filepath.WalkDir(source, func(file string, entry fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		relative, err := filepath.Rel(source, file)
		if err != nil || entry.IsDir() {
			return err
		}
		body, err := os.ReadFile(file)
		if err != nil {
			return err
		}
		writeFixture(t, root, filepath.ToSlash(relative), body)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return root
}

func TestMigrationConvertsUneditedStartersCleanly(t *testing.T) {
	for _, name := range []string{"workspace", "project"} {
		t.Run(name, func(t *testing.T) {
			root := legacyFixture(t, name)
			before := snapshot(t, root)
			plan, err := Migrate(root, "0.3.0", MigrationOptions{}, false)
			if err != nil || len(plan.Conflicts) != 0 || len(plan.Notes) != 0 || plan.Applied || !reflect.DeepEqual(before, snapshot(t, root)) {
				t.Fatalf("preview: %+v %v", plan, err)
			}
			applied, err := Migrate(root, "0.3.0", MigrationOptions{}, true)
			if err != nil || !applied.Applied || applied.Backup == "" {
				t.Fatalf("apply: %+v %v", applied, err)
			}
			for _, gone := range []string{"AI.md", "guidance", "WSUP-LICENSE", ".wsup", "workspace.json", "apps/.gitkeep", "infrastructure", ".agents/skills/repository-change"} {
				if _, err := os.Lstat(filepath.Join(root, gone)); !os.IsNotExist(err) {
					t.Errorf("%s survived migration", gone)
				}
			}
			after := snapshot(t, root)
			for name := range before {
				// Every file the migration replaced or removed has a backup.
				if strings.HasPrefix(name, ".wsup") || before[name] == "directory" || after[name] == before[name] {
					continue
				}
				if _, err := os.Stat(filepath.Join(root, applied.Backup, name)); err != nil {
					t.Errorf("no backup of %s", name)
				}
			}
			result, err := guidance.Inspect(root)
			if err != nil || len(result.Errors) != 0 {
				t.Fatalf("guidance after migration: %+v %v", result, err)
			}
			if findings, err := CheckLinks(root); err != nil || len(findings) != 0 {
				t.Fatalf("links: %v %v", findings, err)
			}
			if name == "workspace" {
				if data, err := registry.Load(root); err != nil || data.Name != "My workspace" {
					t.Fatalf("registry: %+v %v", data, err)
				}
			}
			settled, err := Update(root, "0.3.0", nil, false)
			if err != nil || len(settled.Actions) != 0 || len(settled.Conflicts) != 0 {
				t.Fatalf("migrated %s does not settle: %+v %v", name, settled, err)
			}
			if _, err := Migrate(root, "0.3.0", MigrationOptions{}, false); err == nil {
				t.Fatal("migrated starter migrated again")
			}
		})
	}
}

func TestMigrationKeepsOwnerEditsAndConvertsTheRegistry(t *testing.T) {
	root := legacyFixture(t, "workspace")
	writeFixture(t, root, "README.md", []byte("Owner readme\n"))
	writeFixture(t, root, "AI.md", []byte("Owner guidance\n"))
	writeFixture(t, root, ".agents/skills/repository-change/SKILL.md", []byte("Owner skill\n"))
	writeFixture(t, root, "infrastructure/cloud/README.md", []byte("Cloud\n"))
	writeFixture(t, root, ".wsup/reports/old.json", []byte("evidence"))
	writeFixture(t, root, "wsup.json", []byte(`{"version":1,"settings":{"timeout_seconds":60,"report_dir":".wsup/reports/ci"}}`))
	writeFixture(t, root, "wsup.local.json", []byte(`{"version":1,"settings":{"report_dir":".wsup/reports/local"}}`))
	writeFixture(t, root, "workspace.json", []byte(`{"version":1,"name":"Legacy","projects":[{"id":"cloud","path":"infrastructure/cloud","kind":"infrastructure","repository":"workspace","purpose":"Cloud","owner":"Ops","checks":{"plan":["terraform","plan"],"audit":{"command":["audit"],"mode":"report"}}}]}`))
	plan, err := Migrate(root, "0.3.0", MigrationOptions{Agents: []string{"claude"}, Editors: []string{"none"}}, true)
	if err != nil || !plan.Applied {
		t.Fatalf("apply: %+v %v", plan, err)
	}
	for _, kept := range []string{"README.md", "AI.md", ".agents/skills/repository-change/SKILL.md"} {
		if !slices.Contains(plan.Actions, Action{kept, "keep"}) {
			t.Errorf("%s not kept: %+v", kept, plan.Actions)
		}
	}
	if body, err := os.ReadFile(filepath.Join(root, "README.md")); err != nil || string(body) != "Owner readme\n" {
		t.Fatal("owner README changed")
	}
	notes := strings.Join(plan.Notes, "\n")
	for _, want := range []string{"AI.md was edited", "now make-change", "infrastructure/ is now infra/", "Project cloud is under infrastructure/", "Reports in .wsup/reports/"} {
		if !strings.Contains(notes, want) {
			t.Errorf("missing note %q in:\n%s", want, notes)
		}
	}
	if body, err := os.ReadFile(filepath.Join(root, "workbench/.local/wsup/reports/old.json")); err != nil || string(body) != "evidence" {
		t.Fatal("reports not moved")
	}
	document, err := registry.Decode(must(os.ReadFile(filepath.Join(root, "wsup.json"))))
	if err != nil {
		t.Fatal(err)
	}
	project := document.Projects[0]
	if document.Name != "Legacy" || project.Kind != "infra" || len(project.Tasks) != 2 || project.Tasks[0].Name != "plan" ||
		!project.Tasks[0].IsCheck || project.Tasks[1].Check.Mode != "report" ||
		document.Settings["report_dir"] != "workbench/.local/wsup/reports/ci" ||
		!reflect.DeepEqual(document.Agents, []string{"claude"}) || len(document.Editors) != 0 {
		t.Fatalf("converted wsup.json: %+v", document)
	}
	if local := string(must(os.ReadFile(filepath.Join(root, "wsup.local.json")))); !strings.Contains(local, "workbench/.local/wsup/reports/local") {
		t.Fatalf("local settings: %s", local)
	}
	// The kept README keeps its 0.2.0 baseline, so update reports it until the
	// owner keeps or replaces it.
	plan2, err := Update(root, "0.3.0", nil, false)
	if err != nil || !reflect.DeepEqual(plan2.Conflicts, []string{"README.md"}) {
		t.Fatalf("update after migration: %+v %v", plan2, err)
	}
	if kept, err := Update(root, "0.3.0", []string{"README.md"}, true); err != nil || !kept.Applied {
		t.Fatalf("keep after migration: %+v %v", kept, err)
	}
}

func TestMigrationConflictsBlockEveryWrite(t *testing.T) {
	for name, setup := range map[string]func(root string){
		"owner CLAUDE.md": func(root string) { writeFixture(t, root, "CLAUDE.md", []byte("Owner instructions\n")) },
		"reports already moved": func(root string) {
			writeFixture(t, root, ".wsup/reports/a.json", []byte("a"))
			writeFixture(t, root, "workbench/.local/wsup/reports/b.json", []byte("b"))
		},
	} {
		root := legacyFixture(t, "workspace")
		setup(root)
		before := snapshot(t, root)
		plan, err := Migrate(root, "0.3.0", MigrationOptions{}, true)
		if err == nil || plan.Applied || len(plan.Conflicts) == 0 || !reflect.DeepEqual(before, snapshot(t, root)) {
			t.Fatalf("%s: %+v %v", name, plan, err)
		}
	}
	for name, setup := range map[string]func(root string){
		"outside report_dir": func(root string) {
			writeFixture(t, root, "wsup.json", []byte(`{"version":1,"settings":{"report_dir":"elsewhere"}}`))
		},
		"invalid registry": func(root string) { writeFixture(t, root, "workspace.json", []byte("{")) },
		"no state":         func(root string) { _ = os.RemoveAll(filepath.Join(root, ".wsup")) },
	} {
		root := legacyFixture(t, "workspace")
		setup(root)
		before := snapshot(t, root)
		if _, err := Migrate(root, "0.3.0", MigrationOptions{}, true); err == nil || !reflect.DeepEqual(before, snapshot(t, root)) {
			t.Fatalf("%s accepted or wrote: %v", name, err)
		}
	}
}

func TestMigrationMapsRetiredCollections(t *testing.T) {
	root := legacyFixture(t, "workspace")
	state := must(os.ReadFile(filepath.Join(root, ".wsup/template-state.json")))
	state = []byte(strings.Replace(string(state), `"template": "workspace",`, `"template": "workspace", "collections": ["artifacts", "private"],`, 1))
	writeFixture(t, root, ".wsup/template-state.json", state)
	writeFixture(t, root, "artifacts/v1.zip", []byte("release"))
	writeFixture(t, root, "private/notes.md", []byte("secret"))
	plan, err := Migrate(root, "0.3.0", MigrationOptions{}, true)
	if err != nil || !plan.Applied || !slices.Contains(plan.Modules, "releases") || slices.Contains(plan.Modules, "private") {
		t.Fatalf("retired collections: %+v %v", plan, err)
	}
	notes := strings.Join(plan.Notes, "\n")
	if !strings.Contains(notes, "artifacts/ is now releases/") || !strings.Contains(notes, "private collection was removed") {
		t.Fatalf("notes: %s", notes)
	}
	for _, kept := range []string{"artifacts/v1.zip", "private/notes.md"} {
		if _, err := os.Stat(filepath.Join(root, kept)); err != nil {
			t.Fatalf("owner content moved or removed: %s", kept)
		}
	}
}
